import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/ON.DXVlsWbj.js";import{_ as t,a as r,b as a,c as o}from"./chunks/M-S-US6a.BRwbLMSt.js";import{_ as n,o as l,c as u,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const j=JSON.parse('{"title":"Mise à jour","description":"","frontmatter":{"source_hash":"874eaebd13","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/update.md","filePath":"fr/use/update.md"}'),d={name:"fr/use/update.md"};function c(m,e,v,h,f,g){return l(),u("div",null,[...e[0]||(e[0]=[p('<p>Vous pouvez mettre à jour xDrip en installant une autre version par-dessus la version actuelle, sans la désinstaller, de la même façon que lors de votre <a href="./../install/download.html">installation</a> d&#39;origine.</p><p>Vous pouvez aussi utiliser le mécanisme de mise à jour interne de xDrip.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> xDrip+ Mises à jour</p></div><p>Les paramètres de mise à jour vous permettent de choisir quelles versions de xDrip vous sont proposées en mise à jour.</p><div class="warning custom-block"><p class="custom-block-title">NE DÉSINSTALLEZ PAS xDRIP+</p><p>Vous pouvez passer à une version plus récente ou plus ancienne de xDrip simplement en l&#39;installant par-dessus la version actuelle.<br> Désinstaller xDrip peut entraîner une perte de données complète et irrécupérable si vous n&#39;avez pas fait de <a href="./../troubleshoot/reinstall.html#reinstall-xdrip">sauvegarde</a>.</p></div><p>Seules les versions officielles de xDrip peuvent utiliser cette fonction.<br> Si vous avez installé une <a href="./../install/download.html#forked-versions">version dérivée (fork)</a>, seul son auteur peut fournir des mises à jour.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>La mise à jour de xDrip est totalement transparente et ne nécessite aucune action particulière sur votre capteur en cours.<br> Vos paramètres sont conservés, sauf si une modification importante a été apportée à un paramètre particulier.<br> Par précaution, il vaut mieux garder un œil sur xDrip si vous avez choisi une version alpha ou nightly.</p></div><p>Vous devriez activer la vérification automatique des mises à jour.</p><div class="admonition xdripitem"><p class="admonition-title">Vérification automatique de mise à jour <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Être informé des nouvelles versions disponibles</p></div><p>Si vous la laissez désactivée, xDrip vous rappellera de faire la mise à jour tous les 60 jours.</p><div class="admonition xdripitem"><p class="admonition-title">Hé Fam...</p><p> Vous avez les contrôles de mise à jour désactivé!<br>  Nous essayons de corriger les bugs et ajouter de nouvelles fonctionnalités à xDrip+ au fil du temps.<br>  Tous les 60 jours ce rappel s&#39;affichera pour vous demander d&#39;activer le contrôle de mises à jour.</p></div><p>Il existe trois canaux de mise à jour :</p><ul><li>Stable : versions publiées dont la stabilité et la fiabilité ont été éprouvées</li><li>Beta : versions candidates à une publication stable</li><li>Alpha : versions en cours de développement</li></ul><p>Un quatrième n&#39;apparaît qu&#39;une fois Alpha sélectionné (voir <a href="#getting-the-nightlies-on-automatic-update">ci-dessous</a>) :</p><ul><li>Nightly : prototypes destinés aux tests</li></ul><p>Les versions les plus testées n&#39;incluent pas les dernières fonctionnalités et corrections.</p><p>Les versions moins testées peuvent contenir des bugs, mais incluent aussi les dernières fonctionnalités et corrections.</p><div class="admonition xdripitem"><p class="admonition-title">Mise à jour du Canal</p><p> Choisir version Stable, Bêta ou Alpha</p></div><div class="admonition xdripitem"><p class="admonition-title">Mise à jour du Canal</p><p> Stable - tried and tested versions (versions éprouvées)<br>  Beta - new features but not fully tested (nouvelles fonctions, pas entièrement testées)<br>  Alpha - versions for early testing (versions pour les premiers tests)<br>  Nightly - untested raw code - experts only! (code brut non testé, experts uniquement !)</p></div><h3 id="getting-the-nightlies-on-automatic-update" tabindex="-1">Recevoir les nightlies par mise à jour automatique <a class="header-anchor" href="#getting-the-nightlies-on-automatic-update" aria-label="Permalink to &quot;Recevoir les nightlies par mise à jour automatique {#getting-the-nightlies-on-automatic-update}&quot;">​</a></h3><p>Le canal Nightly est masqué tant que vous n&#39;avez pas sélectionné Alpha une première fois.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> xDrip+ Mises à jour<br>   Mise à jour du Canal</p></div><ol><li>Ouvrez Mise à jour du Canal. Si Nightly figure dans la liste, sélectionnez-le et c&#39;est terminé.</li><li>Si Nightly n&#39;apparaît pas, sélectionnez Alpha, revenez à l&#39;écran d&#39;accueil de xDrip, puis rouvrez xDrip+ Mises à jour et Mise à jour du Canal. Nightly est maintenant visible : sélectionnez-le.</li></ol><div class="warning custom-block"><p class="custom-block-title">Nightly est le canal le moins testé</p><p>Les versions Nightly contiennent le code le plus récent et le moins testé. Elles sont les premières à recevoir les nouvelles fonctions, mais c&#39;est aussi là que les bugs sont généralement découverts. Surveillez xDrip après chaque mise à jour et soyez prêt à <a href="#downgrade">revenir à une version antérieure</a> en installant une version plus ancienne par-dessus.</p></div><p>Les vérifications de mise à jour ont lieu environ toutes les 24 heures. Pour vérifier immédiatement, utilisez <a href="./3dotsmenu.html#check-for-updated-version">Vérifier les mises à jour</a> dans le menu à 3 points.</p><p>Dans le <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">dépôt officiel</a>, vous pouvez identifier la dernière version publiée grâce à l&#39;étiquette Latest.<br> Vous pouvez télécharger la dernière version publiée <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">ici</a>.<br> Toutes les autres portent l&#39;étiquette Pre-release.</p><img src="'+t+'" style="zoom:75%;"><p>Les fonctions de rapport ne sont plus utilisées. Si vous avez besoin d&#39;aide, utilisez les <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussions</a> ou <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Rapport d&#39;erreurs automatique</p></div><div class="admonition xdripitem"><p class="admonition-title">Activer la télémétrie</p></div><p>Les commentaires ne sont plus utilisés. Ne vous en servez que pour envoyer des compliments.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer des commentaires</p></div><h3 id="update" tabindex="-1">Mise à jour <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Mise à jour {#update}&quot;">​</a></h3><p>Vous pouvez mettre à jour xDrip en installant une autre version par-dessus la version actuelle, sans la désinstaller, de la même façon que lors de votre <a href="./../install/download.html">installation</a> d&#39;origine.</p><p>Vous pouvez aussi utiliser le mécanisme de mise à jour interne de xDrip.</p><p>Les notifications de mise à jour disponible se déclenchent selon le canal choisi.<br> Si vous avez désactivé la vérification automatique des mises à jour, vous pouvez lancer une vérification manuellement depuis le <a href="./3dotsmenu.html#check-for-updated-version">menu à 3 points</a>.</p><ol><li>Le canal de mise à jour actuel est affiché</li><li>Versions actuelle et plus récente (disponible)</li><li>Télécharger maintenant lance le téléchargement de la mise à jour ; Android demandera l&#39;autorisation d&#39;installer une fois le téléchargement terminé.</li><li>Vous pouvez désactiver les mises à jour automatiques. Cela a le même effet que le bouton de vérification automatique des mises à jour ci-dessus.</li><li>Si vous n&#39;utilisez pas le téléchargeur interne, votre appareil utilisera l&#39;application par défaut pour télécharger les fichiers depuis Internet.</li><li>Quitter sans rien faire.</li></ol><img src="'+r+'" style="zoom:75%;"><p>Si vous choisissez le téléchargeur interne, une barre de progression s&#39;affiche et, une fois le téléchargement terminé, l&#39;installation démarre automatiquement.</p><img src="'+a+'" style="zoom:75%;"><p>Si vous n&#39;avez pas choisi le téléchargeur interne, votre téléphone télécharge le paquet depuis <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a> et lance l&#39;installation une fois le téléchargement terminé.</p><p>Aucune nouvelle autorisation ne devrait être nécessaire.</p><img src="'+o+'" style="zoom:75%;"><p>Une fois la mise à jour effectuée, vous pouvez vérifier la version actuelle dans l&#39;<a href="./../troubleshoot/systemstatus.html">état du système</a>.</p><h3 id="downgrade" tabindex="-1">Revenir à une version antérieure <a class="header-anchor" href="#downgrade" aria-label="Permalink to &quot;Revenir à une version antérieure {#downgrade}&quot;">​</a></h3><p>Vous n&#39;avez pas besoin de désinstaller xDrip pour revenir à une version plus ancienne (sauf pour <a href="./../troubleshoot/reinstall.html">passer d&#39;une version officielle à une version dérivée</a> ou inversement) : installez simplement la version voulue par-dessus la version actuelle, <a href="./../install/download.html">comme lors de la première installation</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',48)])])}const D=n(d,[["render",c]]);export{j as __pageData,D as default};
